use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\UserGrantedClientScopesRef;

final class UserGrantedClientScopesRefUnitTest extends TestCase
{
    public function test(): void
    {
